   437  /**
   438   * Rearrange point (x, y) in the HEALPix projection by
   439   * combining the polar caps into two polar squares.
   440   * Put the north polar square in position north_square and
   441   * the south polar square in position south_square.
   442   * If inverse=1, then uncombine the polar caps.
   443   * @param north_square integer between 0 and 3.
   444   * @param south_square integer between 0 and 3.
   445   **/
   446  static XY combine_caps(double x, double y, int north_square, int south_square,
   447                         int inverse) {
   448      XY xy;
   449      double v[2];
   450      double c[2];
   451      double vector[2];
   452      double v_min_c[2];
   453      double ret_dot[2];
   454      double (*tmpRot)[2];
   455      int pole = 0;
   456
   457      CapMap capmap = get_cap(x, y, north_square, south_square, inverse);
   458      if (capmap.region == equatorial) {
   459          xy.x = capmap.x;
   460          xy.y = capmap.y;
   461          return xy;
   462      }
   463
   464      v[0] = x; v[1] = y;
   465      c[0] = capmap.x; c[1] = capmap.y;
   466
   467      if (inverse == 0) {
   468          /* Rotate (x, y) about its polar cap tip and then translate it to
   469             north_square or south_square. */
   470
   471          if (capmap.region == north) {
   472              pole = north_square;
   473              tmpRot = rot[get_rotate_index(capmap.cn - pole)];
   474          } else {
   475              pole = south_square;
   476              tmpRot = rot[get_rotate_index(-1*(capmap.cn - pole))];
   477          }
   478      } else {
   479          /* Inverse function.
   480           Unrotate (x, y) and then translate it back. */
   481
   482          /* disassemble */
   483          if (capmap.region == north) {
   484              pole = north_square;
   485              tmpRot = rot[get_rotate_index(-1*(capmap.cn - pole))];
   486          } else {
   487              pole = south_square;
   488              tmpRot = rot[get_rotate_index(capmap.cn - pole)];
   489          }
   490      }
   491
   492      vector_sub(v, c, v_min_c);
   493      dot_product(tmpRot, v_min_c, ret_dot);
   494      {
   495          double a[2];
   496          /* Workaround cppcheck git issue */
   497          double* pa = a;
   498          pa[0] = -3*M_FORTPI + ((inverse == 0) ? 0 : capmap.cn) *M_HALFPI;
   499          pa[1] = M_HALFPI;
   500          vector_add(ret_dot, a, vector);
   501      }
   502
   503      xy.x = vector[0];
   504      xy.y = vector[1];
   505      return xy;
   506  }
